  <script>
    // Broker selection functionality
    const brokerButtons = document.querySelectorAll('.broker-button');
    const brokerFormContainer = document.getElementById('broker-form-container');
    
    brokerButtons.forEach(button => {
      button.addEventListener('click', () => {
        // Remove active class from all buttons
        brokerButtons.forEach(btn => btn.classList.remove('broker-button--active'));
        // Add active class to clicked button
        button.classList.add('broker-button--active');
        
        // Get the URL from data attribute
        const brokerUrl = button.getAttribute('data-url');
        
        // Show form container if URL exists
        if (brokerUrl && brokerUrl.trim() !== '') {
          brokerFormContainer.style.display = 'block';
        } else {
          brokerFormContainer.style.display = 'none';
        }
      });
    });

    // Show VT Markets form container by default since it's active
    const activeButton = document.querySelector('.broker-button--active');
    if (activeButton) {
      const defaultUrl = activeButton.getAttribute('data-url');
      if (defaultUrl && defaultUrl.trim() !== '') {
        brokerFormContainer.style.display = 'block';
      }
    }
  </script>

